import{_ as s,o as t,c as r,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-5-change-password/report3_spec.md","filePath":"feature/authentication/3-2-5-change-password/report3_spec.md"}'),i={name:"feature/authentication/3-2-5-change-password/report3_spec.md"};function o(a,e,l,d,h,g){return t(),r("div",null,[...e[0]||(e[0]=[n("<p><strong>3.2.5 Change Password</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user opens the change-password section under Settings &gt; Security and submits the current password together with a new password and its confirmation.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any authenticated USER changing their own password. Applies to any account that already has a password set.</li><li><strong>Purpose</strong>: Let a signed-in user change the password after proving knowledge of the current one, without ending the current session.</li><li><strong>Interface</strong>: A form on Settings &gt; Security with three fields — Current Password, New Password, Confirm New Password — and a submit button.</li><li><strong>Data Processing</strong>: Identifies the caller from the access token, verifies the current password against the stored hash, refuses a new password identical to the current one, replaces the password hash, updates the last-password-change time, and records an audit log event.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Change Password (Settings &gt; Security):</p><ul><li>A card titled &quot;Change Password&quot; with three password inputs: Current Password, New Password, Confirm New Password (client-only confirmation, not sent to the server).</li><li>A single submit button, loading state while in flight.</li><li>On success: a toast confirms the change and the user is navigated to the dashboard; the current session stays signed in.</li><li>On failure: an error message is shown and the form remains filled in for correction.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: currentPassword, newPassword; Authorization Bearer header.</li><li><strong>Input optional</strong>: confirmNewPassword — client-side only, never sent to the server.</li><li><strong>System data</strong>: userId (from the access token), user.passwordHash, user.lastPasswordChange, the audit log entry.</li><li><strong>Output</strong>: no payload, 200.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-02</strong>: Password policy — minimum 8 characters and at least 1 digit; hashed with BCrypt cost=12; never logged or returned.</li><li>Check order: (1) verify currentPassword against the stored hash — mismatch -&gt; 400 WRONG_CURRENT_PASSWORD; (2) only then compare newPassword to the same hash — a match -&gt; 400 SAME_AS_CURRENT_PASSWORD; (3) only then hash and persist the new password.</li><li><strong>BR-12</strong>: Changing the password sets lastPasswordChange = now. A refresh token issued before this timestamp is rejected on its next use, invalidating every outstanding refresh token on every device, even though the current session remains valid.</li><li>The same audit action is reused for both Reset Password and Change Password; there is no distinct &quot;password changed&quot; action.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>currentPassword or newPassword empty -&gt; Display: <strong>MSG02</strong></li><li>newPassword under 8 characters or missing a digit -&gt; Display: <strong>MSG05</strong></li><li>confirmNewPassword mismatch -&gt; Display: <strong>MSG06</strong></li><li>Missing or malformed Authorization header -&gt; 401 INVALID_CREDENTIALS</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user opens Settings &gt; Security and enters the current password, the new password, and the confirmation.</li><li>The client checks the confirmation matches the new password, then submits.</li><li>The system resolves the caller&#39;s userId from the access token and loads the account.</li><li>The system verifies currentPassword against the stored hash.</li><li>The system compares newPassword against the same hash and rejects it if identical.</li><li>The system replaces passwordHash with the BCrypt hash of newPassword, sets lastPasswordChange = now, and writes an audit log entry.</li><li>The system returns 200. The client shows a success toast and navigates to the dashboard; the current session stays signed in, while every outstanding refresh token is invalidated.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Missing or malformed Authorization header -&gt; 401 INVALID_CREDENTIALS. 2.a2: The user is signed out and returned to login.</li><li>3.a1: The account referenced by the token no longer exists -&gt; 404 USER_NOT_FOUND. 3.a2: The user is signed out and must sign in again.</li><li>4.a1: currentPassword does not match the stored hash, checked first -&gt; 400 WRONG_CURRENT_PASSWORD, Display: <strong>MSG19</strong>. 4.a2: The user re-enters the current password.</li><li>5.a1: newPassword is identical to currentPassword, checked only after step 4 passes -&gt; 400 SAME_AS_CURRENT_PASSWORD. 5.a2: The user enters a different new password.</li><li>1.a1: newPassword fails the policy check -&gt; Display: <strong>MSG05</strong>. 1.a2: The user corrects the password and resubmits.</li><li>1.b1: currentPassword or newPassword empty -&gt; Display: <strong>MSG02</strong>. 1.b2: The user fills in the missing field and resubmits.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>user.passwordHash is replaced and user.lastPasswordChange is updated to the change time.</li><li>An audit log entry is recorded for the user.</li><li>The current session remains valid and signed in.</li><li>Every refresh token issued before the change, on this device or any other, is rejected on its next use; the user must sign in again on those other sessions.</li></ul>",14)])])}const p=s(i,[["render",o]]);export{u as __pageData,p as default};
